-- SOURCE REVIEW CANDIDATE / UNRUN. Exactly three composed definitions.
-- No alert, incident, ledger, schedule or operational queue row is changed.
-- Install/replay/rollback are atomic. Mixed component states reject.
DO $component$
DECLARE
  v_rollback constant boolean := true;
  v_images constant jsonb := $images$[{"signature": "public.fn_ca_financial_alert_to_incident()", "pre": "CREATE OR REPLACE FUNCTION public.fn_ca_financial_alert_to_incident()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nDECLARE\n  v_dedupe text;\n  v_echo_id uuid;\n  v_severity text;\n  v_shape text;\nBEGIN\n  IF NEW.severity <> 'critical' THEN RETURN NEW; END IF;\n  IF NEW.source LIKE 'drift_incident:%' THEN RETURN NEW; END IF;\n\n  /* A REFUSED HAND IS A RATE, NOT AN INCIDENT (2026-09-09). */\n  IF NEW.source = 'ServerTableEngine.authoritative_hand_semantic_refusal'\n     OR COALESCE(NEW.context->>'error', '') LIKE '%authoritative_hand_semantic_refusal%' THEN\n    RETURN NEW;\n  END IF;\n\n  /* A HANDOFF THAT NAMES ITS SUCCESSOR IS NOT AN INCIDENT (2026-09-10). */\n  IF NEW.source = 'ServerTableEngine.post_commit_obligations_pending' THEN\n    RETURN NEW;\n  END IF;\n\n  /* ONE CAUSE IS ONE INCIDENT (2026-09-09). The key is the SHAPE of the\n     finding, not its instance. */\n  v_shape := public.fn_ca_normalize_alert_text(left(NEW.message, 200))\n             || '|' ||\n             public.fn_ca_normalize_alert_text(left(COALESCE(NEW.context->>'error', ''), 200));\n\n  v_dedupe := CASE\n      -- A terminal refusal belongs to one tournament. Normalizing the error\n      -- removes its UUID; shape-only folding then mixes different events.\n      -- Without an entity, retain the original alert as its own unknown.\n      WHEN NEW.source = 'Tournament.atomic_finish_refused'\n        THEN 'fa:Tournament.atomic_finish_refused:'\n          || COALESCE(NULLIF(lower(NEW.context->>'tournament_id'), ''),\n                      'alert:' || NEW.id::text)\n          || ':' || md5(v_shape)\n      WHEN NEW.source ~* 'prize_credit_failed' AND NULLIF(NEW.context->>'tournament_id','') IS NOT NULL\n        THEN 'fa:prize_credit_failed:' || (NEW.context->>'tournament_id')\n      ELSE 'fa:' || NEW.source || ':' || md5(v_shape) END;\n\n  SELECT i.id INTO v_echo_id FROM public.ca_drift_incidents i\n   WHERE i.dedupe_key = v_dedupe AND i.status = 'resolved'\n     AND i.resolved_at > now() - interval '48 hours'\n     AND i.suspected_cause = left(NEW.message, 300)\n   ORDER BY i.resolved_at DESC LIMIT 1;\n  IF v_echo_id IS NOT NULL THEN\n    UPDATE public.ca_drift_incidents SET occurrences = occurrences + 1 WHERE id = v_echo_id;\n    INSERT INTO public.ca_incident_events (incident_id, at, kind, actor_label, detail)\n    VALUES (v_echo_id, now(), 'comment', 'system',\n            jsonb_build_object('note', 'Byte-identical echo of this resolved incident re-reported by '\n              || NEW.source || '; folded without re-paging (alert ' || NEW.id || ').'));\n    RETURN NEW;\n  END IF;\n\n  /* A DRIFT INCIDENT IS CRITICAL WHEN CHIPS ARE AT STAKE (2026-09-10). */\n  v_severity := CASE\n      WHEN NEW.source ~* 'conservation' THEN 'info'\n      /* THE ENGINE ALREADY DECIDED THIS ONE (2026-09-12, incident bf4ef6e0).\n         ServerTableEngineSettlement.runStep raises a financial alert ONLY when\n         its moneyCritical argument is true, so every postHandTasks.* row here\n         is already filtered to \"this moves chips\" - the five steps that move\n         none (promo_playthrough, horse_rebuys, chip_continuity, horse_cashouts,\n         deferred_sitouts) never arrive. Re-deciding it in SQL downgraded all of\n         them, on two broken tests: a source-name scan for money words, which\n         'leave_pending' fails while returning a player's whole stack to their\n         wallet; and COALESCE(discrepancy, amount, 0) = 0 as proof of zero, when\n         runStep writes neither key - 0 of 1,551 alerts in seven days carry one,\n         so the test was unconditionally true and this branch could only ever\n         return info. And info is not a colour: fn_ca_raise_drift_incident opens\n         with IF p_severity = 'info' THEN NULL, so six failures across six\n         tables paged nobody. When the engine asserts moves_chips in the\n         context, that fact decides; absent, critical, because absent must fail\n         toward being seen. Compared as text rather than cast to boolean on\n         purpose: this trigger ends in EXCEPTION WHEN OTHERS ... RETURN NEW, so\n         a bad cast would silently stop creating incidents rather than raise. */\n      WHEN NEW.source LIKE 'postHandTasks.%'\n        THEN CASE WHEN lower(COALESCE(NEW.context->>'moves_chips','true')) IN ('false','f','0')\n                  THEN 'info' ELSE 'critical' END\n      WHEN NEW.source LIKE 'ServerTableEngine.%'\n           AND NOT (NEW.source ~* 'prize|payout|bounty|rake|treasury|guarantee|insurance|bbj|rakeback')\n           AND COALESCE(NULLIF(NEW.context->>'discrepancy','')::numeric,\n                        NULLIF(NEW.context->>'amount','')::numeric, 0) = 0\n        THEN 'info'\n      WHEN NEW.source ~* 'prize_credit_failed'\n           AND NULLIF(NEW.context->>'user_id','') IS NOT NULL\n           AND public.fn_ca_is_cert_account((NEW.context->>'user_id')::uuid) THEN 'info'\n      ELSE 'critical' END;\n\n  PERFORM public.fn_ca_raise_drift_incident(\n    p_source         => 'financial_alerts:' || NEW.source,\n    p_classification => CASE\n        WHEN NEW.source ~* 'rake'                   THEN 'incorrect_rake'\n        WHEN NEW.source ~* 'bbj'                    THEN 'bbj_error'\n        WHEN NEW.source ~* 'rakeback'               THEN 'incorrect_rakeback'\n        WHEN NEW.source ~* 'treasury|guarantee'     THEN 'treasury_error'\n        WHEN NEW.source ~* 'payout|prize|bounty'    THEN 'settlement_error'\n        WHEN NEW.source ~* 'insurance'              THEN 'settlement_error'\n        WHEN NEW.source ~* 'conservation'           THEN 'ledger_imbalance'\n        ELSE 'unknown' END,\n    p_severity       => v_severity,\n    p_dedupe_key     => v_dedupe,\n    p_discrepancy    => COALESCE(NULLIF(NEW.context->>'discrepancy','')::numeric,\n                                 NULLIF(NEW.context->>'amount','')::numeric, 0),\n    p_layer          => 'ledger',\n    p_club_id        => NULLIF(NEW.context->>'club_id','')::uuid,\n    p_tournament_id  => NULLIF(NEW.context->>'tournament_id','')::uuid,\n    p_table_id       => NULLIF(NEW.context->>'table_id','')::uuid,\n    p_suspected_cause => left(NEW.message, 300),\n    p_metadata       => COALESCE(NEW.context,'{}'::jsonb) ||\n                        jsonb_build_object('alert_id', NEW.id));\n  RETURN NEW;\nEXCEPTION WHEN OTHERS THEN\n  RAISE WARNING 'fn_ca_financial_alert_to_incident failed: %', SQLERRM;\n  RETURN NEW;\nEND $function$\n", "post": "CREATE OR REPLACE FUNCTION public.fn_ca_financial_alert_to_incident()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nDECLARE\n  v_dedupe text;\n  v_echo_id uuid;\n  v_severity text;\n  v_shape text;\nBEGIN\n  IF NEW.severity <> 'critical' THEN RETURN NEW; END IF;\n  IF NEW.source LIKE 'drift_incident:%' THEN RETURN NEW; END IF;\n\n  /* A REFUSED HAND IS A RATE, NOT AN INCIDENT (2026-09-09). */\n  IF NEW.source = 'ServerTableEngine.authoritative_hand_semantic_refusal'\n     OR COALESCE(NEW.context->>'error', '') LIKE '%authoritative_hand_semantic_refusal%' THEN\n    RETURN NEW;\n  END IF;\n\n  /* A HANDOFF THAT NAMES ITS SUCCESSOR IS NOT AN INCIDENT (2026-09-10). */\n  IF NEW.source = 'ServerTableEngine.post_commit_obligations_pending' THEN\n    RETURN NEW;\n  END IF;\n\n  /* ONE CAUSE IS ONE INCIDENT (2026-09-09). The key is the SHAPE of the\n     finding, not its instance. */\n  v_shape := public.fn_ca_normalize_alert_text(left(NEW.message, 200))\n             || '|' ||\n             public.fn_ca_normalize_alert_text(left(COALESCE(NEW.context->>'error', ''), 200));\n\n  v_dedupe := CASE\n      -- A failed leave can strand this table/hand's stack obligation. Keep its\n      -- exact entity; normalizing hand numbers must not merge another leave.\n      WHEN NEW.source = 'postHandTasks.leave_pending_failed'\n        THEN 'fa:postHandTasks.leave_pending_failed:'\n          || CASE\n              WHEN jsonb_typeof(NEW.context->'table_id') = 'string'\n               AND (NEW.context->>'table_id') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'\n               AND jsonb_typeof(NEW.context->'hand_number') = 'number'\n               AND (NEW.context->>'hand_number') ~ '^[1-9][0-9]*$'\n               AND (length(NEW.context->>'hand_number') < 19\n                    OR (length(NEW.context->>'hand_number') = 19\n                        AND (NEW.context->>'hand_number') COLLATE \"C\" <= '9223372036854775807'))\n              THEN 'table:' || (NEW.context->>'table_id')::uuid::text\n                   || ':hand:' || (NEW.context->>'hand_number')\n              ELSE 'alert:' || NEW.id::text\n             END\n          || ':' || md5(v_shape)\n      -- A terminal refusal belongs to one tournament. Normalizing the error\n      -- removes its UUID; shape-only folding then mixes different events.\n      -- Without an entity, retain the original alert as its own unknown.\n      WHEN NEW.source = 'Tournament.atomic_finish_refused'\n        THEN 'fa:Tournament.atomic_finish_refused:'\n          || COALESCE(NULLIF(lower(NEW.context->>'tournament_id'), ''),\n                      'alert:' || NEW.id::text)\n          || ':' || md5(v_shape)\n      WHEN NEW.source ~* 'prize_credit_failed' AND NULLIF(NEW.context->>'tournament_id','') IS NOT NULL\n        THEN 'fa:prize_credit_failed:' || (NEW.context->>'tournament_id')\n      ELSE 'fa:' || NEW.source || ':' || md5(v_shape) END;\n\n  SELECT i.id INTO v_echo_id FROM public.ca_drift_incidents i\n   WHERE i.dedupe_key = v_dedupe AND i.status = 'resolved'\n     AND i.resolved_at > now() - interval '48 hours'\n     AND i.suspected_cause = left(NEW.message, 300)\n   ORDER BY i.resolved_at DESC LIMIT 1;\n  IF v_echo_id IS NOT NULL THEN\n    UPDATE public.ca_drift_incidents SET occurrences = occurrences + 1 WHERE id = v_echo_id;\n    INSERT INTO public.ca_incident_events (incident_id, at, kind, actor_label, detail)\n    VALUES (v_echo_id, now(), 'comment', 'system',\n            jsonb_build_object('note', 'Byte-identical echo of this resolved incident re-reported by '\n              || NEW.source || '; folded without re-paging (alert ' || NEW.id || ').'));\n    RETURN NEW;\n  END IF;\n\n  /* A DRIFT INCIDENT IS CRITICAL WHEN CHIPS ARE AT STAKE (2026-09-10). */\n  v_severity := CASE\n      WHEN NEW.source ~* 'conservation' THEN 'info'\n      /* THE ENGINE ALREADY DECIDED THIS ONE (2026-09-12, incident bf4ef6e0).\n         ServerTableEngineSettlement.runStep raises a financial alert ONLY when\n         its moneyCritical argument is true, so every postHandTasks.* row here\n         is already filtered to \"this moves chips\" - the five steps that move\n         none (promo_playthrough, horse_rebuys, chip_continuity, horse_cashouts,\n         deferred_sitouts) never arrive. Re-deciding it in SQL downgraded all of\n         them, on two broken tests: a source-name scan for money words, which\n         'leave_pending' fails while returning a player's whole stack to their\n         wallet; and COALESCE(discrepancy, amount, 0) = 0 as proof of zero, when\n         runStep writes neither key - 0 of 1,551 alerts in seven days carry one,\n         so the test was unconditionally true and this branch could only ever\n         return info. And info is not a colour: fn_ca_raise_drift_incident opens\n         with IF p_severity = 'info' THEN NULL, so six failures across six\n         tables paged nobody. When the engine asserts moves_chips in the\n         context, that fact decides; absent, critical, because absent must fail\n         toward being seen. Compared as text rather than cast to boolean on\n         purpose: this trigger ends in EXCEPTION WHEN OTHERS ... RETURN NEW, so\n         a bad cast would silently stop creating incidents rather than raise. */\n      WHEN NEW.source LIKE 'postHandTasks.%'\n        THEN CASE WHEN lower(COALESCE(NEW.context->>'moves_chips','true')) IN ('false','f','0')\n                  THEN 'info' ELSE 'critical' END\n      WHEN NEW.source LIKE 'ServerTableEngine.%'\n           AND NOT (NEW.source ~* 'prize|payout|bounty|rake|treasury|guarantee|insurance|bbj|rakeback')\n           AND COALESCE(NULLIF(NEW.context->>'discrepancy','')::numeric,\n                        NULLIF(NEW.context->>'amount','')::numeric, 0) = 0\n        THEN 'info'\n      WHEN NEW.source ~* 'prize_credit_failed'\n           AND NULLIF(NEW.context->>'user_id','') IS NOT NULL\n           AND public.fn_ca_is_cert_account((NEW.context->>'user_id')::uuid) THEN 'info'\n      ELSE 'critical' END;\n\n  PERFORM public.fn_ca_raise_drift_incident(\n    p_source         => 'financial_alerts:' || NEW.source,\n    p_classification => CASE\n        WHEN NEW.source ~* 'rake'                   THEN 'incorrect_rake'\n        WHEN NEW.source ~* 'bbj'                    THEN 'bbj_error'\n        WHEN NEW.source ~* 'rakeback'               THEN 'incorrect_rakeback'\n        WHEN NEW.source ~* 'treasury|guarantee'     THEN 'treasury_error'\n        WHEN NEW.source ~* 'payout|prize|bounty'    THEN 'settlement_error'\n        WHEN NEW.source ~* 'insurance'              THEN 'settlement_error'\n        WHEN NEW.source ~* 'conservation'           THEN 'ledger_imbalance'\n        ELSE 'unknown' END,\n    p_severity       => v_severity,\n    p_dedupe_key     => v_dedupe,\n    p_discrepancy    => COALESCE(NULLIF(NEW.context->>'discrepancy','')::numeric,\n                                 NULLIF(NEW.context->>'amount','')::numeric, 0),\n    p_layer          => 'ledger',\n    p_club_id        => NULLIF(NEW.context->>'club_id','')::uuid,\n    p_tournament_id  => NULLIF(NEW.context->>'tournament_id','')::uuid,\n    p_table_id       => CASE WHEN NEW.source = 'postHandTasks.leave_pending_failed'\n                            THEN CASE WHEN jsonb_typeof(NEW.context->'table_id') = 'string'\n                                       AND (NEW.context->>'table_id') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'\n                                      THEN (NEW.context->>'table_id')::uuid\n                                      ELSE NULL::uuid END\n                            ELSE NULLIF(NEW.context->>'table_id','')::uuid END,\n    p_suspected_cause => left(NEW.message, 300),\n    p_metadata       => COALESCE(NEW.context,'{}'::jsonb) ||\n                        jsonb_build_object('alert_id', NEW.id));\n  RETURN NEW;\nEXCEPTION WHEN OTHERS THEN\n  RAISE WARNING 'fn_ca_financial_alert_to_incident failed: %', SQLERRM;\n  RETURN NEW;\nEND $function$\n"}, {"signature": "public.fn_ca_raise_drift_incident(text,text,text,text,numeric,numeric,numeric,text,text,uuid,uuid,uuid,uuid,uuid,uuid,text,uuid[],uuid[],text,boolean,jsonb)", "pre": "CREATE OR REPLACE FUNCTION public.fn_ca_raise_drift_incident(p_source text, p_classification text, p_severity text, p_dedupe_key text, p_discrepancy numeric DEFAULT NULL::numeric, p_expected numeric DEFAULT NULL::numeric, p_actual numeric DEFAULT NULL::numeric, p_layer text DEFAULT NULL::text, p_entity_type text DEFAULT NULL::text, p_entity_id uuid DEFAULT NULL::uuid, p_club_id uuid DEFAULT NULL::uuid, p_union_id uuid DEFAULT NULL::uuid, p_table_id uuid DEFAULT NULL::uuid, p_tournament_id uuid DEFAULT NULL::uuid, p_hand_id uuid DEFAULT NULL::uuid, p_settlement_id text DEFAULT NULL::text, p_wallet_ids uuid[] DEFAULT NULL::uuid[], p_transaction_ids uuid[] DEFAULT NULL::uuid[], p_suspected_cause text DEFAULT NULL::text, p_ledger_balanced boolean DEFAULT NULL::boolean, p_metadata jsonb DEFAULT NULL::jsonb)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nDECLARE\n  v_id uuid;\n  v_class text := p_classification;\n  v_sev   text := lower(COALESCE(p_severity,'critical'));\n  v_stable text;\nBEGIN\n  IF NOT public.fn_ca_is_midway_scope(\n    p_union_id, p_club_id, p_table_id, p_tournament_id, p_metadata\n  ) THEN\n    RETURN NULL;\n  END IF;\n  IF EXISTS (SELECT 1 FROM public.ca_detector_registry r WHERE r.source = p_source AND r.status = 'retired') THEN\n    RETURN NULL;\n  END IF;\n  INSERT INTO public.ca_detector_registry (source, owner, sla_hours, note)\n  VALUES (p_source, 'unassigned', 24, 'auto-registered on first sight (Phase 6 gate); give it an owner')\n  ON CONFLICT (source) DO NOTHING;\n\n  IF v_class IS NULL OR v_class NOT IN (\n      'ledger_imbalance','settlement_error','duplicate_payment','missing_payment',\n      'projection_delay','cache_mismatch','reporting_mismatch','delayed_event',\n      'duplicate_event','rounding_error','incorrect_rake','incorrect_weighted_rake',\n      'incorrect_rakeback','bbj_error','treasury_error','credit_line_error',\n      'cross_club_posting','cross_union_posting','unauthorized_adjustment',\n      'historical_migration','unknown') THEN\n    v_class := 'unknown';\n  END IF;\n  IF v_sev NOT IN ('critical','warning','info') THEN v_sev := 'critical'; END IF;\n\n  UPDATE public.ca_drift_incidents\n     SET occurrences  = occurrences + 1,\n         last_seen_at = now(),\n         discrepancy_amount = COALESCE(p_discrepancy, discrepancy_amount),\n         actual_amount      = COALESCE(p_actual, actual_amount),\n         expected_amount    = COALESCE(p_expected, expected_amount),\n         suspected_cause    = COALESCE(p_suspected_cause, suspected_cause),\n         metadata           = COALESCE(p_metadata, metadata)\n   WHERE dedupe_key = p_dedupe_key AND status <> 'resolved'\n   RETURNING id INTO v_id;\n\n  IF v_id IS NOT NULL THEN\n    INSERT INTO public.ca_incident_events (incident_id, kind, detail)\n    VALUES (v_id, 'recurred', jsonb_build_object('source', p_source,\n            'discrepancy', p_discrepancy));\n    RETURN v_id;\n  END IF;\n\n  /* ONE STANDING CONDITION IS ONE INCIDENT (2026-09-06).\n     A sweep that puts the date in its key defeats the exact-match fold above\n     and files a fresh critical every run: sweep:fn_bbj_promo_bank_check:\n     2026-09-02 .. -09-06, five rows, all 6705.21, one condition.\n\n     The amount is what makes this safe. `diamond-unexplained:2026-09-02-18`\n     is an hourly bucket where each bucket is a DIFFERENT event, so folding on\n     the key alone would hide real ones. A standing condition re-reports the\n     same number; a new event reports a new one. Same detector, same key\n     without its period label, same discrepancy - then and only then is it the\n     same finding said twice. */\n  v_stable := public.fn_ca_stable_dedupe_key(p_dedupe_key);\n  IF v_stable <> p_dedupe_key THEN\n    UPDATE public.ca_drift_incidents\n       SET occurrences     = occurrences + 1,\n           last_seen_at    = now(),\n           suspected_cause = COALESCE(p_suspected_cause, suspected_cause),\n           metadata        = COALESCE(p_metadata, metadata)\n     WHERE status <> 'resolved'\n       AND source = p_source\n       AND public.fn_ca_stable_dedupe_key(dedupe_key) = v_stable\n       AND COALESCE(discrepancy_amount,0) = COALESCE(p_discrepancy,0)\n     RETURNING id INTO v_id;\n    IF v_id IS NOT NULL THEN\n      INSERT INTO public.ca_incident_events (incident_id, kind, detail)\n      VALUES (v_id, 'recurred', jsonb_build_object(\n        'source', p_source, 'rotated_key', p_dedupe_key,\n        'note', 'same condition under a new period label; folded rather than re-filed'));\n      RETURN v_id;\n    END IF;\n  END IF;\n\n  /* DETECTOR STORM CAP (2026-09-09). One source cannot own the board.\n     Reached only after the exact-key fold and the stable-key fold above have\n     both declined to absorb this finding, i.e. it really would be a NEW row. */\n  IF (SELECT count(*) FROM public.ca_drift_incidents\n       WHERE source = p_source AND status <> 'resolved') >= 25 THEN\n    UPDATE public.ca_drift_incidents\n       SET occurrences = occurrences + 1, last_seen_at = now()\n     WHERE dedupe_key = 'storm:' || p_source AND status <> 'resolved'\n     RETURNING id INTO v_id;\n    IF v_id IS NULL THEN\n      INSERT INTO public.ca_drift_incidents (\n        classification, severity, layer, source, dedupe_key,\n        discrepancy_amount, suspected_cause, metadata)\n      VALUES ('unknown', v_sev, COALESCE(p_layer,'unknown'), p_source,\n        'storm:' || p_source, 0,\n        'DETECTOR STORM: this source has 25 or more open incidents, so further findings are counted here rather than filed as new rows. Every occurrence is still in financial_alerts and in this incident event log. Fix the detector, or the condition behind it, then resolve this.',\n        jsonb_build_object('storm', true, 'capped_from', p_dedupe_key))\n      ON CONFLICT (dedupe_key) WHERE status <> 'resolved' DO NOTHING\n      RETURNING id INTO v_id;\n      IF v_id IS NULL THEN\n        UPDATE public.ca_drift_incidents\n           SET occurrences = occurrences + 1, last_seen_at = now()\n         WHERE dedupe_key = 'storm:' || p_source AND status <> 'resolved'\n         RETURNING id INTO v_id;\n      END IF;\n    END IF;\n    IF v_id IS NOT NULL THEN\n      INSERT INTO public.ca_incident_events (incident_id, kind, detail)\n      VALUES (v_id, 'recurred', jsonb_build_object(\n        'source', p_source, 'capped_dedupe_key', p_dedupe_key,\n        'discrepancy', p_discrepancy, 'suspected_cause', p_suspected_cause,\n        'note', 'counted on the storm incident: this source is over its open-incident cap'));\n    END IF;\n    RETURN v_id;\n  END IF;\n\n  INSERT INTO public.ca_drift_incidents (\n    classification, severity, layer, source, dedupe_key,\n    union_id, club_id, entity_type, entity_id, table_id, tournament_id,\n    hand_id, settlement_id, wallet_ids, transaction_ids,\n    expected_amount, actual_amount, discrepancy_amount,\n    ledger_balanced, suspected_cause, metadata)\n  VALUES (\n    v_class, v_sev, COALESCE(p_layer,'unknown'), p_source, p_dedupe_key,\n    p_union_id, p_club_id, p_entity_type, p_entity_id, p_table_id, p_tournament_id,\n    p_hand_id, p_settlement_id, p_wallet_ids, p_transaction_ids,\n    p_expected, p_actual, COALESCE(p_discrepancy, 0),\n    p_ledger_balanced, p_suspected_cause, COALESCE(p_metadata,'{}'::jsonb))\n  ON CONFLICT (dedupe_key) WHERE status <> 'resolved' DO NOTHING\n  RETURNING id INTO v_id;\n\n  IF v_id IS NULL THEN\n    UPDATE public.ca_drift_incidents\n       SET occurrences     = occurrences + 1,\n           last_seen_at    = now(),\n           suspected_cause = COALESCE(p_suspected_cause, suspected_cause),\n           metadata        = COALESCE(p_metadata, metadata)\n     WHERE dedupe_key = p_dedupe_key AND status <> 'resolved'\n     RETURNING id INTO v_id;\n    RETURN v_id;\n  END IF;\n\n  INSERT INTO public.ca_incident_events (incident_id, kind, detail)\n  VALUES (v_id, 'created', jsonb_build_object('source', p_source));\n\n  BEGIN\n    PERFORM public.fn_raise_server_financial_alert(\n      v_sev, 'drift_incident:' || p_source,\n      v_class || ' drift ' || COALESCE(p_discrepancy,0)::text || ' chips',\n      jsonb_build_object('incident_id', v_id) || COALESCE(p_metadata,'{}'::jsonb));\n  EXCEPTION WHEN OTHERS THEN NULL;\n  END;\n\n  IF p_severity = 'info' THEN\n    NULL;\n  ELSIF (SELECT count(*) FROM public.ca_drift_incidents\n       WHERE created_at > now() - interval '2 minutes') >= 10 THEN\n    INSERT INTO public.ca_incident_events (incident_id, kind, detail)\n    VALUES (v_id, 'notified', jsonb_build_object('storm_suppressed', true));\n  ELSE\n    PERFORM public.fn_ca_incident_notify(\n      v_id, 'notified',\n      to_char(COALESCE(p_discrepancy,0),'FM999999999990.00') || ' chip drift: ' || v_class,\n      false);\n  END IF;\n\n  RETURN v_id;\nEXCEPTION WHEN OTHERS THEN\n  DECLARE v_state text; v_msg text;\n  BEGIN\n    GET STACKED DIAGNOSTICS v_state = RETURNED_SQLSTATE, v_msg = MESSAGE_TEXT;\n    RAISE WARNING 'fn_ca_raise_drift_incident(%) failed: %', p_source, v_msg;\n    BEGIN\n      INSERT INTO public.ca_incident_file_failures\n        (source, dedupe_key, classification, severity, discrepancy, sqlstate, message)\n      VALUES (p_source, p_dedupe_key, v_class, v_sev, p_discrepancy, v_state, v_msg);\n    EXCEPTION WHEN OTHERS THEN\n      NULL;\n    END;\n    RETURN NULL;\n  END;\nEND $function$\n", "post": "CREATE OR REPLACE FUNCTION public.fn_ca_raise_drift_incident(p_source text, p_classification text, p_severity text, p_dedupe_key text, p_discrepancy numeric DEFAULT NULL::numeric, p_expected numeric DEFAULT NULL::numeric, p_actual numeric DEFAULT NULL::numeric, p_layer text DEFAULT NULL::text, p_entity_type text DEFAULT NULL::text, p_entity_id uuid DEFAULT NULL::uuid, p_club_id uuid DEFAULT NULL::uuid, p_union_id uuid DEFAULT NULL::uuid, p_table_id uuid DEFAULT NULL::uuid, p_tournament_id uuid DEFAULT NULL::uuid, p_hand_id uuid DEFAULT NULL::uuid, p_settlement_id text DEFAULT NULL::text, p_wallet_ids uuid[] DEFAULT NULL::uuid[], p_transaction_ids uuid[] DEFAULT NULL::uuid[], p_suspected_cause text DEFAULT NULL::text, p_ledger_balanced boolean DEFAULT NULL::boolean, p_metadata jsonb DEFAULT NULL::jsonb)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nDECLARE\n  v_id uuid;\n  v_class text := p_classification;\n  v_sev   text := lower(COALESCE(p_severity,'critical'));\n  v_stable text;\nBEGIN\n  IF NOT public.fn_ca_is_midway_scope(\n    p_union_id, p_club_id, p_table_id, p_tournament_id, p_metadata\n  ) THEN\n    RETURN NULL;\n  END IF;\n  IF EXISTS (SELECT 1 FROM public.ca_detector_registry r WHERE r.source = p_source AND r.status = 'retired') THEN\n    RETURN NULL;\n  END IF;\n  INSERT INTO public.ca_detector_registry (source, owner, sla_hours, note)\n  VALUES (p_source, 'unassigned', 24, 'auto-registered on first sight (Phase 6 gate); give it an owner')\n  ON CONFLICT (source) DO NOTHING;\n\n  IF v_class IS NULL OR v_class NOT IN (\n      'ledger_imbalance','settlement_error','duplicate_payment','missing_payment',\n      'projection_delay','cache_mismatch','reporting_mismatch','delayed_event',\n      'duplicate_event','rounding_error','incorrect_rake','incorrect_weighted_rake',\n      'incorrect_rakeback','bbj_error','treasury_error','credit_line_error',\n      'cross_club_posting','cross_union_posting','unauthorized_adjustment',\n      'historical_migration','unknown') THEN\n    v_class := 'unknown';\n  END IF;\n  IF v_sev NOT IN ('critical','warning','info') THEN v_sev := 'critical'; END IF;\n\n  UPDATE public.ca_drift_incidents\n     SET occurrences  = occurrences + 1,\n         last_seen_at = now(),\n         discrepancy_amount = COALESCE(p_discrepancy, discrepancy_amount),\n         actual_amount      = COALESCE(p_actual, actual_amount),\n         expected_amount    = COALESCE(p_expected, expected_amount),\n         suspected_cause    = COALESCE(p_suspected_cause, suspected_cause),\n         metadata           = COALESCE(p_metadata, metadata)\n   WHERE dedupe_key = p_dedupe_key AND status <> 'resolved'\n   RETURNING id INTO v_id;\n\n  IF v_id IS NOT NULL THEN\n    INSERT INTO public.ca_incident_events (incident_id, kind, detail)\n    VALUES (v_id, 'recurred', jsonb_build_object('source', p_source,\n            'discrepancy', p_discrepancy));\n    RETURN v_id;\n  END IF;\n\n  /* ONE STANDING CONDITION IS ONE INCIDENT (2026-09-06).\n     A sweep that puts the date in its key defeats the exact-match fold above\n     and files a fresh critical every run: sweep:fn_bbj_promo_bank_check:\n     2026-09-02 .. -09-06, five rows, all 6705.21, one condition.\n\n     The amount is what makes this safe. `diamond-unexplained:2026-09-02-18`\n     is an hourly bucket where each bucket is a DIFFERENT event, so folding on\n     the key alone would hide real ones. A standing condition re-reports the\n     same number; a new event reports a new one. Same detector, same key\n     without its period label, same discrepancy - then and only then is it the\n     same finding said twice. */\n  v_stable := public.fn_ca_stable_dedupe_key(p_dedupe_key);\n  IF v_stable <> p_dedupe_key THEN\n    UPDATE public.ca_drift_incidents\n       SET occurrences     = occurrences + 1,\n           last_seen_at    = now(),\n           suspected_cause = COALESCE(p_suspected_cause, suspected_cause),\n           metadata        = COALESCE(p_metadata, metadata)\n     WHERE status <> 'resolved'\n       AND source = p_source\n       AND public.fn_ca_stable_dedupe_key(dedupe_key) = v_stable\n       AND COALESCE(discrepancy_amount,0) = COALESCE(p_discrepancy,0)\n     RETURNING id INTO v_id;\n    IF v_id IS NOT NULL THEN\n      INSERT INTO public.ca_incident_events (incident_id, kind, detail)\n      VALUES (v_id, 'recurred', jsonb_build_object(\n        'source', p_source, 'rotated_key', p_dedupe_key,\n        'note', 'same condition under a new period label; folded rather than re-filed'));\n      RETURN v_id;\n    END IF;\n  END IF;\n\n  /* DETECTOR STORM CAP (2026-09-09). One source cannot own the board.\n     Reached only after the exact-key fold and the stable-key fold above have\n     both declined to absorb this finding, i.e. it really would be a NEW row. */\n  IF (SELECT count(*) FROM public.ca_drift_incidents\n       WHERE source = p_source AND status <> 'resolved') >= 25 THEN\n    UPDATE public.ca_drift_incidents\n       SET occurrences = occurrences + 1, last_seen_at = now()\n     WHERE dedupe_key = 'storm:' || p_source AND status <> 'resolved'\n     RETURNING id INTO v_id;\n    IF v_id IS NULL THEN\n      INSERT INTO public.ca_drift_incidents (\n        classification, severity, layer, source, dedupe_key,\n        discrepancy_amount, suspected_cause, metadata)\n      VALUES ('unknown', v_sev, COALESCE(p_layer,'unknown'), p_source,\n        'storm:' || p_source, 0,\n        'DETECTOR STORM: this source has 25 or more open incidents, so further findings are counted here rather than filed as new rows. See this incident''s event log for the original capped finding keys and reported discrepancies; this branch does not create a separate financial_alerts row for each finding. Fix the detector, or the condition behind it, then resolve this.',\n        jsonb_build_object('storm', true, 'capped_from', p_dedupe_key))\n      ON CONFLICT (dedupe_key) WHERE status <> 'resolved' DO NOTHING\n      RETURNING id INTO v_id;\n      IF v_id IS NULL THEN\n        UPDATE public.ca_drift_incidents\n           SET occurrences = occurrences + 1, last_seen_at = now()\n         WHERE dedupe_key = 'storm:' || p_source AND status <> 'resolved'\n         RETURNING id INTO v_id;\n      END IF;\n    END IF;\n    IF v_id IS NOT NULL THEN\n      INSERT INTO public.ca_incident_events (incident_id, kind, detail)\n      VALUES (v_id, 'recurred', jsonb_build_object(\n        'source', p_source, 'capped_dedupe_key', p_dedupe_key,\n        'discrepancy', p_discrepancy, 'suspected_cause', p_suspected_cause,\n        'note', 'counted on the storm incident: this source is over its open-incident cap'));\n    END IF;\n    RETURN v_id;\n  END IF;\n\n  INSERT INTO public.ca_drift_incidents (\n    classification, severity, layer, source, dedupe_key,\n    union_id, club_id, entity_type, entity_id, table_id, tournament_id,\n    hand_id, settlement_id, wallet_ids, transaction_ids,\n    expected_amount, actual_amount, discrepancy_amount,\n    ledger_balanced, suspected_cause, metadata)\n  VALUES (\n    v_class, v_sev, COALESCE(p_layer,'unknown'), p_source, p_dedupe_key,\n    p_union_id, p_club_id, p_entity_type, p_entity_id, p_table_id, p_tournament_id,\n    p_hand_id, p_settlement_id, p_wallet_ids, p_transaction_ids,\n    p_expected, p_actual, COALESCE(p_discrepancy, 0),\n    p_ledger_balanced, p_suspected_cause, COALESCE(p_metadata,'{}'::jsonb))\n  ON CONFLICT (dedupe_key) WHERE status <> 'resolved' DO NOTHING\n  RETURNING id INTO v_id;\n\n  IF v_id IS NULL THEN\n    UPDATE public.ca_drift_incidents\n       SET occurrences     = occurrences + 1,\n           last_seen_at    = now(),\n           suspected_cause = COALESCE(p_suspected_cause, suspected_cause),\n           metadata        = COALESCE(p_metadata, metadata)\n     WHERE dedupe_key = p_dedupe_key AND status <> 'resolved'\n     RETURNING id INTO v_id;\n    RETURN v_id;\n  END IF;\n\n  INSERT INTO public.ca_incident_events (incident_id, kind, detail)\n  VALUES (v_id, 'created', jsonb_build_object('source', p_source));\n\n  BEGIN\n    PERFORM public.fn_raise_server_financial_alert(\n      v_sev, 'drift_incident:' || p_source,\n      v_class || ' drift ' || COALESCE(p_discrepancy,0)::text || ' chips',\n      jsonb_build_object('incident_id', v_id) || COALESCE(p_metadata,'{}'::jsonb));\n  EXCEPTION WHEN OTHERS THEN NULL;\n  END;\n\n  IF p_severity = 'info' THEN\n    NULL;\n  ELSIF (SELECT count(*) FROM public.ca_drift_incidents\n       WHERE created_at > now() - interval '2 minutes') >= 10 THEN\n    INSERT INTO public.ca_incident_events (incident_id, kind, detail)\n    VALUES (v_id, 'notified', jsonb_build_object('storm_suppressed', true));\n  ELSE\n    PERFORM public.fn_ca_incident_notify(\n      v_id, 'notified',\n      to_char(COALESCE(p_discrepancy,0),'FM999999999990.00') || ' chip drift: ' || v_class,\n      false);\n  END IF;\n\n  RETURN v_id;\nEXCEPTION WHEN OTHERS THEN\n  DECLARE v_state text; v_msg text;\n  BEGIN\n    GET STACKED DIAGNOSTICS v_state = RETURNED_SQLSTATE, v_msg = MESSAGE_TEXT;\n    RAISE WARNING 'fn_ca_raise_drift_incident(%) failed: %', p_source, v_msg;\n    BEGIN\n      INSERT INTO public.ca_incident_file_failures\n        (source, dedupe_key, classification, severity, discrepancy, sqlstate, message)\n      VALUES (p_source, p_dedupe_key, v_class, v_sev, p_discrepancy, v_state, v_msg);\n    EXCEPTION WHEN OTHERS THEN\n      NULL;\n    END;\n    RETURN NULL;\n  END;\nEND $function$\n"}, {"signature": "public.fn_ca_escalate_reconcile_criticals(interval)", "pre": "CREATE OR REPLACE FUNCTION public.fn_ca_escalate_reconcile_criticals(p_lookback interval DEFAULT '36:00:00'::interval)\n RETURNS TABLE(considered integer, filed integer)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nDECLARE\n  r        record;\n  v_seen   integer := 0;\n  v_filed  integer := 0;\n  v_id     uuid;\n  v_class  text;\nBEGIN\n  FOR r IN\n    -- Newest row per entity. An entity critical for a week must not raise\n    -- seven incidents; fn_ca_raise_drift_incident counts the recurrence.\n    /* THE NEWEST ROW DECIDES, NOT THE NEWEST CRITICAL ROW (2026-09-08).\n       The severity filter used to sit in this WHERE, so DISTINCT ON picked\n       the newest CRITICAL row per entity rather than the newest row - and\n       an entity whose latest reading is ok kept re-escalating its last\n       critical for the whole lookback. Deep Stack Society read ok at\n       13:01:35 and was escalated again at 13:52 from a 2026-09-07 row.\n       Every fix in this repo was being undone on the board for 36 hours. */\n    SELECT * FROM (\n      SELECT DISTINCT ON (l.entity_type, l.entity_id)\n             l.entity_type, l.entity_id, l.drift, l.ledger_balance,\n             l.stored_balance, l.run_date, l.metadata, l.severity\n        FROM public.ledger_reconcile_log l\n       WHERE l.created_at >= now() - p_lookback\n       ORDER BY l.entity_type, l.entity_id, l.created_at DESC\n    ) newest WHERE newest.severity = 'critical'\n  LOOP\n    v_seen := v_seen + 1;\n\n    -- Map onto the classifications the estate already routes on rather than\n    -- inventing one; an unknown value silently becomes 'unknown' upstream.\n    v_class := CASE r.entity_type\n      WHEN 'club_treasury'       THEN 'treasury_error'\n      WHEN 'frozen_wallets_pool' THEN 'unauthorized_adjustment'\n      ELSE 'ledger_imbalance'\n    END;\n\n    v_id := public.fn_ca_raise_drift_incident(\n      -- the same source the trigger files under, so one detector owns it\n      'ledger_reconcile_log:' || COALESCE(r.metadata->>'source', r.entity_type),\n      v_class,\n      'critical',\n      -- the same key fn_ca_reconcile_log_to_incident builds, so this folds\n      -- onto the incident that already exists rather than twinning it\n      'lrl:' || r.entity_type || ':' || COALESCE(r.entity_id::text, '-') || ':' ||\n        COALESCE(r.metadata->>'exit_id', r.metadata->>'hand_history_id',\n                 r.metadata->>'hand_id', r.metadata->>'escrow_id', ''),\n      COALESCE(r.drift, 0),\n      r.ledger_balance,\n      r.stored_balance,\n      -- MUST be one of ledger/projection/cache/reporting/settlement/unknown.\n      -- 'database' is not, and passing it is what made 901 calls vanish.\n      'ledger',\n      r.entity_type,\n      r.entity_id,\n      CASE WHEN r.entity_type = 'club_treasury' THEN r.entity_id END,\n      NULL, NULL, NULL, NULL, NULL, NULL, NULL,\n      'reconcile_ledger_nightly reported a critical drift for this '\n        || r.entity_type || ': the stored balance and the journal disagree.',\n      false,\n      COALESCE(r.metadata, '{}'::jsonb)\n        || jsonb_build_object('run_date', r.run_date,\n                              'escalated_by', 'fn_ca_escalate_reconcile_criticals')\n    );\n\n    -- NULL means the incident was not filed. Today that is almost always\n    -- fn_ca_is_midway_scope declining an entity outside the piloted union,\n    -- which is deliberate; anything else now leaves a row in\n    -- ca_incident_file_failures instead of disappearing.\n    IF v_id IS NOT NULL THEN\n      v_filed := v_filed + 1;\n    END IF;\n  END LOOP;\n\n  considered := v_seen;\n  filed := v_filed;\n  RETURN NEXT;\nEND;\n$function$\n", "post": "CREATE OR REPLACE FUNCTION public.fn_ca_escalate_reconcile_criticals(p_lookback interval DEFAULT '36:00:00'::interval)\n RETURNS TABLE(considered integer, filed integer)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nDECLARE\n  r        record;\n  v_seen   integer := 0;\n  v_filed  integer := 0;\n  v_id     uuid;\n  v_class  text;\nBEGIN\n  FOR r IN\n    -- Newest row per entity. An entity critical for a week must not raise\n    -- seven incidents; fn_ca_raise_drift_incident counts the recurrence.\n    /* THE NEWEST ROW DECIDES, NOT THE NEWEST CRITICAL ROW (2026-09-08).\n       The severity filter used to sit in this WHERE, so DISTINCT ON picked\n       the newest CRITICAL row per entity rather than the newest row - and\n       an entity whose latest reading is ok kept re-escalating its last\n       critical for the whole lookback. Deep Stack Society read ok at\n       13:01:35 and was escalated again at 13:52 from a 2026-09-07 row.\n       Every fix in this repo was being undone on the board for 36 hours. */\n    SELECT * FROM (\n      SELECT DISTINCT ON (l.entity_type, l.entity_id)\n             l.entity_type, l.entity_id, l.drift, l.ledger_balance,\n             l.stored_balance, l.run_date, l.metadata, l.severity\n        FROM public.ledger_reconcile_log l\n       WHERE l.created_at >= now() - p_lookback\n       ORDER BY l.entity_type, l.entity_id, l.created_at DESC\n    ) newest WHERE newest.severity = 'critical'\n  LOOP\n    v_seen := v_seen + 1;\n\n    -- Map onto the classifications the estate already routes on rather than\n    -- inventing one; an unknown value silently becomes 'unknown' upstream.\n    v_class := CASE r.entity_type\n      WHEN 'club_treasury'       THEN 'treasury_error'\n      WHEN 'frozen_wallets_pool' THEN 'unauthorized_adjustment'\n      ELSE 'ledger_imbalance'\n    END;\n\n    v_id := public.fn_ca_raise_drift_incident(\n      -- the same source the trigger files under, so one detector owns it\n      'ledger_reconcile_log:' || COALESCE(r.metadata->>'source', r.entity_type),\n      v_class,\n      'critical',\n      -- the same key fn_ca_reconcile_log_to_incident builds, so this folds\n      -- onto the incident that already exists rather than twinning it\n      'lrl:' || r.entity_type || ':' || COALESCE(r.entity_id::text, '-') || ':' ||\n        COALESCE(r.metadata->>'exit_id', r.metadata->>'hand_history_id',\n                 r.metadata->>'hand_id', r.metadata->>'escrow_id', ''),\n      COALESCE(r.drift, 0),\n      r.ledger_balance,\n      r.stored_balance,\n      -- MUST be one of ledger/projection/cache/reporting/settlement/unknown.\n      -- 'database' is not, and passing it is what made 901 calls vanish.\n      'ledger',\n      r.entity_type,\n      r.entity_id,\n      CASE WHEN r.entity_type = 'club_treasury' THEN r.entity_id END,\n      NULL, NULL, NULL, NULL, NULL, NULL, NULL,\n      CASE WHEN r.entity_type = 'rake_law'\n        THEN 'The rake-law monitor reported a critical finding about recorded rake and the rake specification. This finding alone does not establish a stored-balance/journal disagreement.'\n        ELSE 'reconcile_ledger_nightly reported a critical drift for this '\n          || r.entity_type || ': the stored balance and the journal disagree.'\n      END,\n      false,\n      COALESCE(r.metadata, '{}'::jsonb)\n        || jsonb_build_object('run_date', r.run_date,\n                              'escalated_by', 'fn_ca_escalate_reconcile_criticals')\n    );\n\n    -- NULL means the incident was not filed. Today that is almost always\n    -- fn_ca_is_midway_scope declining an entity outside the piloted union,\n    -- which is deliberate; anything else now leaves a row in\n    -- ca_incident_file_failures instead of disappearing.\n    IF v_id IS NOT NULL THEN\n      v_filed := v_filed + 1;\n    END IF;\n  END LOOP;\n\n  considered := v_seen;\n  filed := v_filed;\n  RETURN NEXT;\nEND;\n$function$\n"}]$images$::jsonb;
  v_signatures text[] := ARRAY[]::text[];
  v_oids oid[] := ARRAY[]::oid[];
  v_pre text[] := ARRAY[]::text[];
  v_post text[] := ARRAY[]::text[];
  v_is_post boolean[] := ARRAY[]::boolean[];
  v_target text[];
  v_image jsonb;
  v_actual text;
  v_dep record;
  v_i integer;
  v_pass integer;
  v_replay boolean;
  v_input_rollback boolean;
  v_ref text;
  v_hash text;
  v_oid oid;
BEGIN
  PERFORM set_config('lock_timeout','5s',true);
  PERFORM set_config('search_path','public',true);
  LOCK TABLE public.financial_alerts IN SHARE ROW EXCLUSIVE MODE;
  FOR v_image IN SELECT value FROM jsonb_array_elements(v_images) LOOP
    v_i := coalesce(array_length(v_oids,1),0)+1;
    v_signatures[v_i] := v_image->>'signature';
    v_oids[v_i] := to_regprocedure(v_signatures[v_i]);
    IF v_oids[v_i] IS NULL THEN RAISE EXCEPTION 'alert core: missing target %',v_signatures[v_i]; END IF;
    v_pre[v_i] := v_image->>'pre'; v_post[v_i] := v_image->>'post';
    v_actual := pg_get_functiondef(v_oids[v_i]);
    IF v_actual IS DISTINCT FROM v_pre[v_i] AND v_actual IS DISTINCT FROM v_post[v_i] THEN
      RAISE EXCEPTION 'alert core: exact target source drift %',v_signatures[v_i];
    END IF;
    v_is_post[v_i] := v_actual = v_post[v_i];
  END LOOP;
  IF array_length(v_oids,1) IS DISTINCT FROM 3 OR v_is_post[1] IS DISTINCT FROM v_is_post[2]
     OR v_is_post[1] IS DISTINCT FROM v_is_post[3] THEN
    RAISE EXCEPTION 'alert core: mixed input state is not install/replay/rollback';
  END IF;
  v_oid := v_oids[1];
  v_target := CASE WHEN v_rollback THEN v_pre ELSE v_post END;
  v_replay := v_is_post[1] = (NOT v_rollback);
  v_ref := CASE WHEN v_rollback THEN 'rollback component production-alert-identity-and-rake-wording'
           ELSE 'component production-alert-identity-and-rake-wording' END;
  v_input_rollback := NOT v_is_post[1] AND EXISTS(SELECT 1 FROM public.ca_guard_defs
    WHERE proname='fn_ca_financial_alert_to_incident'
      AND declared_ref='rollback component production-alert-identity-and-rake-wording');
  IF v_rollback AND NOT v_is_post[1] AND NOT v_input_rollback THEN
    RAISE EXCEPTION 'alert core: rollback replay requires its exact prior declaration';
  END IF;
  FOR v_pass IN 1..2 LOOP
    FOR v_i IN 1..3 LOOP
      IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=v_oids[v_i]
        AND pg_get_userbyid(p.proowner)='postgres' AND p.prosecdef
        AND p.proconfig IS NOT DISTINCT FROM ARRAY['search_path=public']::text[]
        AND p.proacl::text IS NOT DISTINCT FROM '{postgres=X/postgres,service_role=X/postgres}')
        OR (SELECT count(*) FROM pg_proc p WHERE p.pronamespace='public'::regnamespace
          AND p.proname=split_part(split_part(v_signatures[v_i],'.',2),'(',1)) <> 1 THEN
        RAISE EXCEPTION 'alert core: authority/overload drift %',v_signatures[v_i];
      END IF;
    END LOOP;
    FOR v_dep IN SELECT * FROM (VALUES
      ('public.fn_ca_normalize_alert_text(text)', '78487a7deab6ad124e9ff6d25e5e870a', false, NULL::text[], '{=X/postgres,postgres=X/postgres,anon=X/postgres,authenticated=X/postgres,service_role=X/postgres}'),
      ('public.fn_ca_is_midway_scope(uuid,uuid,uuid,uuid,jsonb)', 'a5a8bb3048872ea4c8acf58f1f64390d', true, ARRAY['search_path=public']::text[], '{postgres=X/postgres,service_role=X/postgres}'),
      ('public.fn_ca_stable_dedupe_key(text)', 'c894c79fd08c95666e25d6f0ee4f11d0', false, NULL::text[], '{=X/postgres,postgres=X/postgres,anon=X/postgres,authenticated=X/postgres,service_role=X/postgres}'),
      ('public.fn_ca_is_cert_account(uuid)', 'fc72ec9fdc035fb51d052eefa9308e74', true, ARRAY['search_path=public, pg_temp']::text[], '{postgres=X/postgres,service_role=X/postgres,authenticated=X/postgres}'),
      ('public.fn_ca_alert_resolution_reaches_the_incident()', 'dbe622139f98faf98bca7bc30db0155c', true, ARRAY['search_path=public']::text[], '{postgres=X/postgres,service_role=X/postgres}'),
      ('public.fn_ca_declare_guard_redefinition(text,text)', '3a3746dc6e0a5b7a1db97805588c0eb8', true, ARRAY['search_path=public']::text[], '{postgres=X/postgres,service_role=X/postgres}'),
      ('public.fn_ca_guard_watchlist()', '92ee208d0887728444bda396d0b4d442', false, ARRAY['search_path=public']::text[], '{postgres=X/postgres,service_role=X/postgres}'),
      ('public.fn_ca_incident_notify(uuid,text,text,boolean)', 'ad9a51b31ec9d8f52a416e5e77a033a2', true, ARRAY['search_path=public']::text[], '{postgres=X/postgres,service_role=X/postgres}'),
      ('public.fn_ca_reconcile_log_to_incident()', '250e01bd25b0c3a8777f8242b53191fe', true, ARRAY['search_path=public']::text[], '{postgres=X/postgres,service_role=X/postgres}'),
      ('public.fn_raise_server_financial_alert(text,text,text,jsonb,text,text)', '264d32bcba8f6430ea68b7ca9738fbc8', true, ARRAY['search_path=public']::text[], '{postgres=X/postgres,service_role=X/postgres}')
    ) AS d(signature,definition_md5,secdef,config,acl) LOOP
      IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=to_regprocedure(v_dep.signature)
        AND pg_get_userbyid(p.proowner)='postgres' AND p.prosecdef=v_dep.secdef
        AND p.proconfig IS NOT DISTINCT FROM v_dep.config
        AND p.proacl::text IS NOT DISTINCT FROM v_dep.acl
        AND md5(pg_get_functiondef(p.oid))=v_dep.definition_md5) THEN
        RAISE EXCEPTION 'alert core: dependency/authority drift %',v_dep.signature;
      END IF;
    END LOOP;
    IF NOT ('fn_ca_financial_alert_to_incident'=ANY(public.fn_ca_guard_watchlist()))
       OR NOT ('fn_ca_raise_drift_incident'=ANY(public.fn_ca_guard_watchlist()))
       OR 'fn_ca_escalate_reconcile_criticals'=ANY(public.fn_ca_guard_watchlist())
       OR EXISTS(SELECT 1 FROM public.ca_guard_defs WHERE proname='fn_ca_escalate_reconcile_criticals') THEN
      RAISE EXCEPTION 'alert core: explicit watchlist mode drift';
    END IF;
    -- Before declaration on both passes, the baseline must still describe INPUT.
    FOR v_i IN 1..2 LOOP
      IF NOT EXISTS(SELECT 1 FROM public.ca_guard_defs d
        WHERE d.proname=split_part(split_part(v_signatures[v_i],'.',2),'(',1)
          AND d.def_hash=md5(CASE WHEN v_is_post[v_i] THEN v_post[v_i] ELSE v_pre[v_i] END)
          AND CASE WHEN v_is_post[v_i] THEN d.declared_ref='component production-alert-identity-and-rake-wording'
              WHEN v_input_rollback THEN d.declared_ref='rollback component production-alert-identity-and-rake-wording'
              WHEN v_i=1 THEN d.declared_ref='migration 20260914092500_tournament_finish_incident_identity'
              ELSE d.declared_ref IS NULL AND d.declared_at IS NULL END) THEN
        RAISE EXCEPTION 'alert core: declared input baseline drift %',v_signatures[v_i];
      END IF;
    END LOOP;
    IF (SELECT count(*) FROM pg_attribute a JOIN (VALUES
          ('id', 'uuid'::regtype, true), ('source', 'text'::regtype, true),
          ('message', 'text'::regtype, true), ('severity', 'text'::regtype, true),
          ('context', 'jsonb'::regtype, false)
        ) AS expected(name, type_oid, required_notnull)
        ON a.attname = expected.name AND a.atttypid = expected.type_oid
          AND a.attnotnull = expected.required_notnull
        WHERE a.attrelid = 'public.financial_alerts'::regclass
          AND a.attnum > 0 AND NOT a.attisdropped) <> 5 THEN
      RAISE EXCEPTION 'leave_pending identity: financial-alert identity schema drift';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint c JOIN pg_index x ON x.indexrelid = c.conindid
          WHERE c.conrelid = 'public.financial_alerts'::regclass
            AND c.conname = 'financial_alerts_pkey' AND c.contype = 'p' AND c.convalidated
            AND pg_get_constraintdef(c.oid) = 'PRIMARY KEY (id)'
            AND x.indisprimary AND x.indisunique AND x.indisvalid AND x.indisready) THEN
      RAISE EXCEPTION 'leave_pending identity: original-alert UUID uniqueness drift';
    END IF;
    IF (SELECT count(*) FROM pg_trigger
          WHERE tgrelid = 'public.financial_alerts'::regclass AND NOT tgisinternal) <> 2
       OR NOT EXISTS (SELECT 1 FROM pg_trigger t
          WHERE t.tgrelid = 'public.financial_alerts'::regclass
            AND t.tgname = 'trg_ca_financial_alert_incident' AND t.tgfoid = v_oid
            AND t.tgtype = 5 AND t.tgenabled = 'O' AND t.tgqual IS NULL
            AND t.tgnargs = 0 AND NOT t.tgisinternal AND NOT t.tgdeferrable AND NOT t.tginitdeferred)
       OR NOT EXISTS (SELECT 1 FROM pg_trigger t
          WHERE t.tgrelid = 'public.financial_alerts'::regclass
            AND t.tgname = 'zz_ca_alert_resolution_reaches_the_incident'
            AND t.tgfoid = 'public.fn_ca_alert_resolution_reaches_the_incident()'::regprocedure
            AND md5(pg_get_functiondef(t.tgfoid)) = 'dbe622139f98faf98bca7bc30db0155c'
            AND t.tgtype = 17 AND t.tgenabled = 'O' AND t.tgqual IS NULL
            AND t.tgnargs = 0 AND NOT t.tgisinternal AND NOT t.tgdeferrable AND NOT t.tginitdeferred
            AND pg_get_triggerdef(t.oid) = 'CREATE TRIGGER zz_ca_alert_resolution_reaches_the_incident AFTER UPDATE OF resolved ON public.financial_alerts FOR EACH ROW EXECUTE FUNCTION fn_ca_alert_resolution_reaches_the_incident()') THEN
      RAISE EXCEPTION 'leave_pending identity: financial-alert trigger binding drift';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_index x WHERE x.indexrelid = to_regclass('public.ux_ca_drift_incidents_open_dedupe')
       AND x.indisunique AND x.indisvalid AND x.indisready
       AND pg_get_indexdef(x.indexrelid) = 'CREATE UNIQUE INDEX ux_ca_drift_incidents_open_dedupe ON public.ca_drift_incidents USING btree (dedupe_key) WHERE (status <> ''resolved''::text)') THEN
      RAISE EXCEPTION 'leave_pending identity: active incident uniqueness drift';
    END IF;

    IF (SELECT count(*) FROM pg_trigger WHERE tgrelid='public.ledger_reconcile_log'::regclass AND NOT tgisinternal) <> 1
       OR NOT EXISTS (SELECT 1 FROM pg_trigger t
          WHERE t.tgrelid='public.ledger_reconcile_log'::regclass
            AND t.tgname='trg_ca_reconcile_log_incident' AND t.tgenabled='O'
            AND t.tgtype=5 AND t.tgnargs=0 AND t.tgqual IS NULL
            AND NOT t.tgisinternal AND NOT t.tgdeferrable AND NOT t.tginitdeferred
            AND t.tgfoid='public.fn_ca_reconcile_log_to_incident()'::regprocedure
            AND pg_get_triggerdef(t.oid)='CREATE TRIGGER trg_ca_reconcile_log_incident AFTER INSERT ON public.ledger_reconcile_log FOR EACH ROW EXECUTE FUNCTION fn_ca_reconcile_log_to_incident()') THEN
      RAISE EXCEPTION 'rake wording: reconcile trigger binding drift';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_index x WHERE x.indexrelid=to_regclass('public.ux_ca_drift_incidents_open_dedupe')
          AND x.indisunique AND x.indisvalid AND x.indisready
          AND pg_get_indexdef(x.indexrelid)='CREATE UNIQUE INDEX ux_ca_drift_incidents_open_dedupe ON public.ca_drift_incidents USING btree (dedupe_key) WHERE (status <> ''resolved''::text)')
       OR NOT EXISTS (SELECT 1 FROM pg_index x WHERE x.indexrelid=to_regclass('public.ca_guard_defs_pkey')
          AND x.indisprimary AND x.indisunique AND x.indisvalid AND x.indisready
          AND pg_get_indexdef(x.indexrelid)='CREATE UNIQUE INDEX ca_guard_defs_pkey ON public.ca_guard_defs USING btree (proname)') THEN
      RAISE EXCEPTION 'rake wording: identity index drift';
    END IF;

    IF v_pass=1 AND NOT v_replay THEN
      FOR v_i IN 1..3 LOOP EXECUTE v_target[v_i]; END LOOP;
    END IF;
    FOR v_i IN 1..3 LOOP
      IF pg_get_functiondef(v_oids[v_i]) IS DISTINCT FROM v_target[v_i] THEN
        RAISE EXCEPTION 'alert core: exact target readback failed %',v_signatures[v_i];
      END IF;
    END LOOP;
  END LOOP;
  FOR v_i IN 1..2 LOOP
    IF NOT v_replay THEN
      v_hash := public.fn_ca_declare_guard_redefinition(
        split_part(split_part(v_signatures[v_i],'.',2),'(',1),v_ref);
      IF v_hash IS DISTINCT FROM md5(v_target[v_i]) THEN
        RAISE EXCEPTION 'alert core: declaration receipt mismatch %',v_signatures[v_i];
      END IF;
    END IF;
    IF NOT EXISTS(SELECT 1 FROM public.ca_guard_defs d
      WHERE d.proname=split_part(split_part(v_signatures[v_i],'.',2),'(',1)
        AND d.def_hash=md5(v_target[v_i]) AND d.declared_ref=v_ref)
      OR NOT EXISTS(SELECT 1 FROM public.ca_guard_def_history h
        WHERE h.proname=split_part(split_part(v_signatures[v_i],'.',2),'(',1)
          AND h.def_hash=md5(v_target[v_i]) AND h.def_text=v_target[v_i]) THEN
      RAISE EXCEPTION 'alert core: final declaration/history mismatch %',v_signatures[v_i];
    END IF;
  END LOOP;
END;
$component$;
